<?php require_once 'config.php';require_role(['admin']);$pdo=db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_FILES['sqlfile'])&&is_uploaded_file($_FILES['sqlfile']['tmp_name'])){$sql=file_get_contents($_FILES['sqlfile']['tmp_name']);if(strlen($sql)>15*1024*1024)$msg='Fichier trop volumineux (15 Mo maximum).';elseif(stripos($sql,'CREATE DATABASE')!==false||stripos($sql,'DROP DATABASE')!==false)$msg='Le fichier contient une commande interdite.';else{try{$pdo->beginTransaction();$pdo->exec($sql);$pdo->commit();audit('RESTORE','database',null,'Restauration SQL');$msg='Restauration terminée.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg='Échec de restauration : vérifiez le fichier SQL et sa compatibilité.';}}}}$page_title='Sauvegarde et restauration';include 'partials/header.php';?><div class="panel"><h2>Télécharger une sauvegarde SQL</h2><p>Conservez ce fichier dans un emplacement sûr. Il contient les données financières et les comptes utilisateurs.</p><a class="btn primary" href="backup_download.php">Télécharger la sauvegarde</a></div><div class="panel"><h2>Restaurer une sauvegarde</h2><p>Attention : la restauration peut remplacer des données existantes. Effectuez d'abord une sauvegarde récente.</p><?php if($msg):?><div class="notice"><?=h($msg)?></div><?php endif?><form method="post" enctype="multipart/form-data" class="stack"><?=csrf_field()?><label>Fichier SQL</label><input type="file" name="sqlfile" accept=".sql" required><button class="btn primary" onclick="return confirm('Confirmez-vous la restauration SQL ?')">Restaurer</button></form></div><div class="panel"><h2>Historique de sécurité</h2><div class="table-wrap"><table><tr><th>Date</th><th>Utilisateur</th><th>Action</th><th>Table</th><th>Détails</th></tr><?php foreach($pdo->query('SELECT l.*,u.full_name FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 200') as $l):?><tr><td><?=h($l['created_at'])?></td><td><?=h($l['full_name']??'Compte supprimé')?></td><td><?=h($l['action'])?></td><td><?=h($l['table_name'])?></td><td><?=h($l['details'])?></td></tr><?php endforeach?></table></div></div><?php include 'partials/footer.php';?>